#!/usr/bin/env bash
# Build the WAF against headers and feature flags generated by this OpenResty build.
set -euo pipefail
if [[ $# != 3 ]]; then
    echo "Usage: $0 ATTACHMENT_SOURCE CONFIGURED_NGINX_TREE STAGING_ROOT" >&2
    exit 2
fi
source_dir=$(realpath "$1")
nginx_dir=$(realpath "$2")
stage_dir=$(realpath -m "$3")
test -s "$nginx_dir/objs/ngx_auto_config.h"
test -s "$nginx_dir/objs/Makefile"
build_dir=$(mktemp -d)
trap 'rm -rf "$build_dir"' EXIT
inputs="$build_dir/inputs/nginx-src"
mkdir -p "$inputs"

# The attachment's CMake build consumes the include paths and flags from nginx.
# Expand make variables in the original configured tree including OpenResty's modules.
make -s --no-print-directory -C "$nginx_dir" -f objs/Makefile -f - aegis-print-includes <<'MAKE' > "$build_dir/includes"
aegis-print-includes:
	@printf '%s\n' $(ALL_INCS)
MAKE
while IFS= read -r flag; do
    if [[ $flag == -I ]]; then
        IFS= read -r path || { echo "Missing nginx include directory after -I" >&2; exit 1; }
    elif [[ $flag == -I* ]]; then
        path=${flag#-I}
    else
        echo "Unexpected nginx include flag: $flag" >&2
        exit 1
    fi
    if [[ $path != /* ]]; then path="$nginx_dir/$path"; fi
    printf '%s\n' "$path"
done < "$build_dir/includes" > "$inputs/include_paths.mk"
test -s "$inputs/include_paths.mk"

# ABI-defining macros are in ngx_auto_config.h. Preserve any explicit definitions
# supplied directly on the engine's compiler command line as well.
make -s --no-print-directory -C "$nginx_dir" -f objs/Makefile -f - aegis-print-defines <<'MAKE' > "$inputs/cc_flags.mk"
aegis-print-defines:
	@printf '%s\n' '$(filter -D%,$(CFLAGS))'
MAKE
cmake -S "$source_dir" -B "$build_dir/cmake" \
    -DCMAKE_BUILD_TYPE=Release -DCMAKE_SKIP_RPATH=ON \
    -DCMAKE_INSTALL_PREFIX="$build_dir/inputs"
cmake --build "$build_dir/cmake" --parallel "${BUILD_JOBS:-2}" --target ngx_module

artifact_root="$build_dir/cmake"
install -Dm644 "$artifact_root/attachments/nginx/ngx_module/libngx_module.so" \
    "$stage_dir/usr/lib/nginx/modules/libngx_module.so"
for library in core/shmem_ipc/libosrc_shmem_ipc.so \
               core/compression/libosrc_compression_utils.so \
               attachments/nginx/nginx_attachment_util/libosrc_nginx_attachment_util.so; do
    install -Dm644 "$artifact_root/$library" "$stage_dir/usr/lib/${library##*/}"
done
# Distribution of the rebuilt attachment includes its upstream license and notices.
for notice in LICENSE NOTICE; do
    install -Dm644 "$source_dir/$notice" "$stage_dir/usr/share/doc/aegis-openappsec-attachment/$notice"
done
